public class Main {
    static int calculateSubtotal(int price, int quantity) {
        return price * quantity;
    }

    static int calculateDiscount(int subtotal, int membershipLevel) {
        if (membershipLevel == 2) {
            if (subtotal >= 5000) {
                return subtotal * 15 / 100;
            }
            return subtotal * 10 / 100;
        }
        if (subtotal >= 5000) {
            return subtotal * 10 / 100;
        }
        return 0;
    }

    static int calculateFinalAmount(int subtotal, int discount) {
        return subtotal - discount;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int price = Integer.parseInt(sc.next());
        int quantity = Integer.parseInt(sc.next());
        int membershipLevel = Integer.parseInt(sc.next());
        int subtotal = calculateSubtotal(price, quantity);
        int discount = calculateDiscount(subtotal, membershipLevel);
        int finalAmount = calculateFinalAmount(subtotal, discount);
        System.out.println(subtotal);
        System.out.println(discount);
        System.out.println(finalAmount);
    }
}

