import java.util.Scanner;

public class Main {
    static boolean canTransfer(int balance, int amount) {
        return amount > 0 && amount <= balance;
    }

    static int withdraw(int balance, int amount) {
        return balance - amount;
    }

    static int deposit(int balance, int amount) {
        return balance + amount;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int senderBalance = Integer.parseInt(sc.next());
        int receiverBalance = Integer.parseInt(sc.next());
        int amount = Integer.parseInt(sc.next());
        if (canTransfer(senderBalance, amount)) {
            senderBalance = withdraw(senderBalance, amount);
            receiverBalance = deposit(receiverBalance, amount);
            System.out.println("Transfer Approved");
        } else {
            System.out.println("Transfer Rejected");
        }
        System.out.println(senderBalance);
        System.out.println(receiverBalance);
    }
}

