import java.util.Scanner;

public class Main {
    static int calculatePay(int hoursWorked) {
        if (hoursWorked <= 8) {
            return hoursWorked * 200;
        }
        return 8 * 200 + (hoursWorked - 8) * 300;
    }

    static int calculateBonus(int baseSalary, int rating) {
        if (rating == 5) {
            return baseSalary * 15 / 100;
        } else if (rating == 4) {
            return baseSalary * 10 / 100;
        } else if (rating == 3) {
            return baseSalary * 5 / 100;
        }
        return 0;
    }

    static int calculateGrossPay(int baseSalary, int pay, int bonus) {
        return baseSalary + pay + bonus;
    }

    static int calculateTax(int grossPay) {
        if (grossPay >= 50000) {
            return grossPay * 20 / 100;
        } else if (grossPay >= 30000) {
            return grossPay * 10 / 100;
        }
        return 0;
    }

    static int calculateNetPay(int grossPay, int tax) {
        return grossPay - tax;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int baseSalary = Integer.parseInt(sc.next());
        int hoursWorked = Integer.parseInt(sc.next());
        int rating = Integer.parseInt(sc.next());
        int pay = calculatePay(hoursWorked);
        int bonus = calculateBonus(baseSalary, rating);
        int grossPay = calculateGrossPay(baseSalary, pay, bonus);
        int tax = calculateTax(grossPay);
        int netPay = calculateNetPay(grossPay, tax);
        System.out.println(pay);
        System.out.println(bonus);
        System.out.println(grossPay);
        System.out.println(tax);
        System.out.println(netPay);
    }
}
